```yaml
name: Auto-Approve Copilot Workflows

on:
  pull_request:
    types: [opened, synchronize, reopened]

permissions:
  pull-requests: write
  contents: read

jobs:
  auto-approve:
    runs-on: ubuntu-latest
    if: github.actor == 'github-copilot' || github.actor == 'github-copilot-agent'
    steps:
      - name: Auto-approve PR
        uses: actions/github-script@v6
        with:
          script: |
            const pr = context.payload.pull_request;
            if (!pr) {
              core.error('No pull request found');
              return;
            }

            // Check if the PR is from a Copilot actor
            const actor = context.payload.sender.login;
            if (actor !== 'github-copilot' && actor !== 'github-copilot-agent') {
              core.info('PR not from Copilot, skipping auto-approval');
              return;
            }

            // Check if already approved
            const { data: reviews } = await github.rest.pulls.listReviews({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: pr.number
            });

            const existingApprovals = reviews.filter(r => r.state === 'APPROVED');
            if (existingApprovals.length > 0) {
              core.info('PR already approved, skipping');
              return;
            }

            // Approve the PR
            await github.rest.pulls.createReview({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: pr.number,
              event: 'APPROVE',
              body: 'Auto-approved by GitHub Actions workflow for Copilot PRs.'
            });

            core.info(`Approved PR #${pr.number}`);
```

